CREATE TABLE IF NOT EXISTS student_guidance_achievements (
  achievement_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, evaluation_year varchar(4) NOT NULL, management_item_code varchar(50) NOT NULL, organization_code varchar(50) NOT NULL, occurred_date date NOT NULL, guidance_start_date date NOT NULL, guidance_end_date date NOT NULL, student_count integer NOT NULL CHECK (student_count > 0), achievement_detail text, certification_status varchar(30) NOT NULL DEFAULT 'DRAFTING', attachment_ref varchar(200), deleted_yn varchar(1) NOT NULL DEFAULT 'N', created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by bigint NOT NULL, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by bigint NOT NULL, change_reason varchar(500), CONSTRAINT ck_student_guidance_dates CHECK (guidance_end_date >= guidance_start_date), CONSTRAINT ck_student_guidance_status CHECK (certification_status IN ('DRAFTING','SUBMITTED','DEPARTMENT_CONFIRMED','DEPARTMENT_REJECTED','CERTIFIED','CERTIFICATION_RETURNED','EVALUATION_CONFIRMED','DELETED')), CONSTRAINT fk_student_guidance_org FOREIGN KEY (organization_code) REFERENCES organizations(organization_code), CONSTRAINT fk_student_guidance_created FOREIGN KEY (created_by) REFERENCES users(user_id), CONSTRAINT fk_student_guidance_updated FOREIGN KEY (updated_by) REFERENCES users(user_id));
COMMENT ON TABLE student_guidance_achievements IS '교육영역 학생지도 실적의 헤더, 지도기간, 학생수와 인증상태를 보존한다.';
COMMENT ON COLUMN student_guidance_achievements.certification_status IS 'DRAFTING:작성중|SUBMITTED:제출|DEPARTMENT_CONFIRMED:학과장확인|DEPARTMENT_REJECTED:학과장미승인|CERTIFIED:인증|CERTIFICATION_RETURNED:인증반려|EVALUATION_CONFIRMED:평가확정|DELETED:삭제';
COMMENT ON COLUMN student_guidance_achievements.attachment_ref IS '기존 FileStoragePort 파일 식별자 참조 의도 (FK 미선언)';
CREATE TABLE IF NOT EXISTS student_guidance_students (student_guidance_student_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, achievement_id bigint NOT NULL, student_no varchar(50) NOT NULL, student_name varchar(100) NOT NULL, CONSTRAINT uq_student_guidance_student UNIQUE (achievement_id, student_no), CONSTRAINT fk_student_guidance_students_header FOREIGN KEY (achievement_id) REFERENCES student_guidance_achievements(achievement_id) ON DELETE CASCADE);
COMMENT ON TABLE student_guidance_students IS '학생지도 실적별 지도학생의 식별자와 성명을 반복 상세로 보존한다.';
CREATE INDEX IF NOT EXISTS idx_student_guidance_achievements_search ON student_guidance_achievements(evaluation_year, organization_code, certification_status, occurred_date DESC) WHERE deleted_yn='N';
CREATE INDEX IF NOT EXISTS idx_student_guidance_students_achievement ON student_guidance_students(achievement_id);
INSERT INTO excel_upload_templates(template_id,business_type,template_version,effective_date,created_by,updated_by,change_reason) SELECT 'B77-STUDENT-GUIDANCE-V1','STUDENT_GUIDANCE','v1.0',DATE '2026-01-01',user_id,user_id,'B77 학생지도 Excel 양식' FROM users WHERE login_id='admin' ON CONFLICT (template_id) DO NOTHING;
INSERT INTO excel_upload_template_rules(rule_id,template_id,required_column,column_order,code_rule_ref,created_by,updated_by) SELECT seed.rule_id,'B77-STUDENT-GUIDANCE-V1',seed.column_name,seed.column_order,'STUDENT_GUIDANCE',u.user_id,u.user_id FROM users u CROSS JOIN (VALUES ('B77-SG-RULE-1','관리항목코드',1),('B77-SG-RULE-2','소속조직코드',2),('B77-SG-RULE-3','업적발생일',3),('B77-SG-RULE-4','지도시작일',4),('B77-SG-RULE-5','지도종료일',5),('B77-SG-RULE-6','학생번호',6),('B77-SG-RULE-7','학생명',7)) seed(rule_id,column_name,column_order) WHERE u.login_id='admin' ON CONFLICT (rule_id) DO NOTHING;
INSERT INTO student_guidance_achievements(evaluation_year,management_item_code,organization_code,occurred_date,guidance_start_date,guidance_end_date,student_count,achievement_detail,certification_status,created_by,updated_by,change_reason) SELECT '2026','EDU_GUIDANCE','KNUE-COL-EDU',DATE '2026-03-01',DATE '2026-03-01',DATE '2026-06-30',1,seed.detail,seed.status,1,1,'B77-SG-001 fixture' FROM (VALUES ('B77-SG-001 정상 학생지도','DRAFTING'),('B77-SG-001 제출 학생지도','SUBMITTED'),('B77-SG-001 평가확정 학생지도','EVALUATION_CONFIRMED')) seed(detail,status) WHERE NOT EXISTS (SELECT 1 FROM student_guidance_achievements a WHERE a.achievement_detail=seed.detail);
